param([string]$BaseUrl="https://lab-multiplayer.onrender.com",[ValidateSet("baseline","lab")][string]$Mode="baseline",[int]$Runs=3)
$ErrorActionPreference="Stop"
function LabTest-ConnectLoop($Credentials,[int]$AfterSeq){$s=[Net.WebSockets.ClientWebSocket]::new();$u=$BaseUrl.Replace("https://","wss://").Replace("http://","ws://")+"/v1/ws";$s.ConnectAsync([Uri]$u,[Threading.CancellationToken]::None).GetAwaiter().GetResult()|Out-Null;$h=@{type="resume";protocol=1;roomId=$Credentials.roomId;playerId=$Credentials.playerId;resumeToken=$Credentials.resumeToken;afterSeq=$AfterSeq;mode=$Mode}|ConvertTo-Json -Compress;$b=[Text.Encoding]::UTF8.GetBytes($h);$s.SendAsync([ArraySegment[byte]]::new($b),[Net.WebSockets.WebSocketMessageType]::Text,$true,[Threading.CancellationToken]::None).GetAwaiter().GetResult()|Out-Null;return $s}
function LabTest-ReadLoop($s){$c=[Threading.CancellationTokenSource]::new([TimeSpan]::FromSeconds(10));try{$b=New-Object byte[] 65536;$p=[Text.StringBuilder]::new();do{$r=$s.ReceiveAsync([ArraySegment[byte]]::new($b),$c.Token).GetAwaiter().GetResult();[void]$p.Append([Text.Encoding]::UTF8.GetString($b,0,$r.Count))}while(-not $r.EndOfMessage);return $p.ToString()|ConvertFrom-Json}finally{$c.Dispose()}}
function LabTest-SendLoop($s,[string]$id,[uint64]$seq,[int]$actor,[string]$prefix){$m=@{type="trusted_command";action=@{commandId=$id;seq=$seq;expectedSeq=$seq;actorIndex=$actor;kind="trusted_command";command=@{type="priority_action";action_ref=@{kind="reconnect_loop_test"}};prefixHash=$prefix}}|ConvertTo-Json -Depth 10 -Compress;$b=[Text.Encoding]::UTF8.GetBytes($m);$s.SendAsync([ArraySegment[byte]]::new($b),[Net.WebSockets.WebSocketMessageType]::Text,$true,[Threading.CancellationToken]::None).GetAwaiter().GetResult()|Out-Null}
function LabTest-CloseLoop($s){try{$s.CloseAsync([Net.WebSockets.WebSocketCloseStatus]::NormalClosure,"loop",[Threading.CancellationToken]::None).GetAwaiter().GetResult()|Out-Null}catch{$s.Abort()};$s.Dispose()}
function LabTest-RunLoop([int]$run){$room=Invoke-RestMethod "$BaseUrl/v1/rooms" -Method Post -ContentType "application/json" -Body '{"name":"A"}';$guest=Invoke-RestMethod "$BaseUrl/v1/rooms/$($room.roomId)/players" -Method Post -ContentType "application/json" -Body '{"name":"B"}';$a=LabTest-ConnectLoop $room 0;$b=LabTest-ConnectLoop $guest 0;$null=LabTest-ReadLoop $a;$null=LabTest-ReadLoop $b;$prefix="";LabTest-SendLoop $a "loop-$run-0" 0 $room.playerIndex $prefix;$first=LabTest-ReadLoop $a;$null=LabTest-ReadLoop $b;$prefix=$first.event.prefixHash;$current=1;$reconnects=0;for($i=1;$i -le 5;$i++){LabTest-CloseLoop $b;LabTest-SendLoop $a "loop-$run-$i" $current $room.playerIndex $prefix;$e=LabTest-ReadLoop $a;$prefix=$e.event.prefixHash;$current++;$b=LabTest-ConnectLoop $guest ($current-1);$resume=LabTest-ReadLoop $b;if(@($resume.events).Count -ne 1){throw "unexpected replay count during reconnect $i"};$reconnects++};LabTest-SendLoop $b "loop-$run-guest" $current $guest.playerIndex $prefix;$final=LabTest-ReadLoop $b;$null=LabTest-ReadLoop $a;$diag=Invoke-RestMethod "$BaseUrl/v1/rooms/$($room.roomId)/diagnostics" -Method Post -ContentType "application/json" -Body (ConvertTo-Json @{playerId=$guest.playerId;resumeToken=$guest.resumeToken});$result=[ordered]@{mode=$Mode;run=$run;roomId=$room.roomId;reconnects=$reconnects;finalSeq=$final.event.seq;diagnosticsSeq=$diag.room.currentSeq;duplicates=$diag.room.metrics.duplicates;conflicts=$diag.room.metrics.conflicts};LabTest-CloseLoop $a;LabTest-CloseLoop $b;return $result}
1..$Runs|ForEach-Object{LabTest-RunLoop $_}
